SELECT (s.atr_percent>=0.25) AS high_atr, w.execution_reason, s.decision, s.market_regime, COUNT(*) AS n, SUM(p.realized_pnl>0) AS wins, SUM(p.realized_pnl<0) AS losses, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_gross_pct FROM paper_position p JOIN trade_signal s ON s.id=p.signal_id JOIN wallet_trade w ON w.signal_id=p.signal_id AND w.side='BUY' WHERE p.opened_at>='2026-10-11 00:00:00' AND p.status IN ('CLOSED','STOPPED') GROUP BY high_atr, w.execution_reason, s.decision, s.market_regime ORDER BY high_atr DESC, n DESC LIMIT 80